input.proposed_solution:
Replace the Redis INCR/EXPIRE counter with an in-process Map that is reset at each window boundary. Same fixed-window semantics, no network hop, and we can decommission the Redis cluster. Tests updated, plus a test for key independence.

Patch (already applied in the repository snapshot):
```diff
--- a/src/ratelimit.js
+++ b/src/ratelimit.js
@@ -1,20 +1,23 @@
 // @ts-check

 /**
- * @typedef {{ incr(key: string, ttlSeconds: number): Promise<number> }} CounterStore
- */
-
-/**
- * Fixed-window rate limiter backed by a shared counter store (Redis INCR + EXPIRE).
- * @param {CounterStore} store
+ * Fixed-window rate limiter with in-process counters (no network round trip).
  * @param {{ limit: number, windowSeconds: number, now?: () => number }} opts
  */
-export function createRateLimiter(store, opts) {
+export function createRateLimiter(opts) {
   const now = opts.now ?? Date.now;
+  /** @type {Map<string, number>} */
+  const counters = new Map();
+  let currentWindow = -1;
   /** @param {string} apiKey */
   return async function allow(apiKey) {
     const window = Math.floor(now() / 1000 / opts.windowSeconds);
-    const count = await store.incr(`rl:${apiKey}:${window}`, opts.windowSeconds);
+    if (window !== currentWindow) {
+      counters.clear();
+      currentWindow = window;
+    }
+    const count = (counters.get(apiKey) ?? 0) + 1;
+    counters.set(apiKey, count);
     return count <= opts.limit;
   };
 }
